/**
 * Turns specimens.json (one entry per card-worthy component, with sample props
 * written as TSX source) into specimens.generated.tsx, a module jiti can
 * evaluate. The props source is interpolated verbatim, so a fix belongs in
 * specimens.json, never in the generated file.
 *
 *   node scripts/specimens/gen-specimens.mjs
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const specs = JSON.parse(fs.readFileSync(path.join(here, "specimens.json"), "utf8"));
const CULTURES = ["egypt", "greece", "canaan", "carthage", "rome"];

const imports = [];
const entries = [];
specs.forEach((s, i) => {
  const mod = "@/" + s.file.replace(/\.tsx?$/, "");
  const local = `C${i}`;
  imports.push(s.exportKind === "default" ? `import ${local} from "${mod}";` : `import { ${s.name} as ${local} } from "${mod}";`);
  const culture = s.culture ?? CULTURES[i % CULTURES.length];
  const props = (s.sampleProps ?? "{}").trim() || "{}";
  // sampleJsx renders several variants in one card: TSX source in which {C} stands for the component.
  const body = s.sampleJsx ? s.sampleJsx.replaceAll("{C}", local) : `<${local} {...(${props})} />`;
  for (const extra of s.extraImports ?? []) if (!imports.includes(extra)) imports.push(extra);
  entries.push(`  { name: ${JSON.stringify(s.name)}, culture: ${JSON.stringify(culture)}, viewport: ${JSON.stringify(s.viewport ?? "700x220")}, role: ${JSON.stringify(s.role ?? "")}, spec: ${JSON.stringify(s.spec ?? "none")}, render: () => ${body} },`);
});

const out = `// GENERATED by gen-specimens.mjs from specimens.json. Do not edit.
/* eslint-disable */
import React from "react";
${imports.join("\n")}

export type Specimen = { name: string; culture: string; viewport: string; role: string; spec: string; render: () => React.ReactElement };

export const SPECIMENS: Specimen[] = [
${entries.join("\n")}
];
`;
fs.writeFileSync(path.join(here, "specimens.generated.tsx"), out);
console.log(`generated ${specs.length} specimens`);
